package cn.local.rainreminder;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;import java.util.concurrent.CopyOnWriteArraySet;
final class AppUpdates {
 static final String FEED="https://raw.githubusercontent.com/yzhao2864-boop/rain-reminder/main/update.json",API_FEED="https://api.github.com/repos/yzhao2864-boop/rain-reminder/releases?per_page=20";
 static final long MAX_APK=80L*1024*1024;static volatile boolean busy,cancelled;static volatile int progress=-1;static volatile String message="",phase="idle";static final Set<Runnable> listeners=new CopyOnWriteArraySet<>();static final Handler main=new Handler(Looper.getMainLooper());
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("updates",0);}
 static String version(Context c){try{return c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName;}catch(Exception e){return "0";}}
 static int compare(String a,String b){String[] x=a.replaceFirst("^v","").split("\\."),y=b.replaceFirst("^v","").split("\\.");for(int i=0;i<Math.max(x.length,y.length);i++){int left=i<x.length?Integer.parseInt(x[i]):0,right=i<y.length?Integer.parseInt(y[i]):0;if(left!=right)return Integer.compare(left,right);}return 0;}
 static final class Info {String version,url,sha,checksum,notes;long size;JSONObject json()throws Exception{return new JSONObject().put("version",version).put("url",url).put("sha",sha).put("checksum",checksum).put("notes",notes).put("size",size);}static Info from(JSONObject j){Info i=new Info();i.version=j.optString("version");i.url=j.optString("url");i.sha=j.optString("sha");i.checksum=j.optString("checksum");i.notes=j.optString("notes");i.size=j.optLong("size");return i;}}
 static boolean allowed(String value){try{URL u=new URL(value);String host=u.getHost();return u.getProtocol().equals("https")&&u.getUserInfo()==null&&(u.getPort()==-1||u.getPort()==443)&&(host.equals("api.github.com")||host.equals("raw.githubusercontent.com")||host.equals("github.com")||host.equals("release-assets.githubusercontent.com")||host.equals("objects.githubusercontent.com"));}catch(Exception e){return false;}}
 static Info select(JSONArray releases,String current)throws Exception{Info best=null;for(int n=0;n<releases.length();n++){JSONObject release=releases.optJSONObject(n);if(release==null||release.optBoolean("draft"))continue;String tag=release.optString("tag_name"),v=tag.replaceFirst("^v","");if(!v.matches("[0-9]{1,4}(?:\\.[0-9]{1,4}){1,3}")||compare(v,current)<=0)continue;JSONArray assets=release.optJSONArray("assets");if(assets==null)continue;Info found=null;String checksum="";for(int k=0;k<assets.length();k++){JSONObject asset=assets.optJSONObject(k);if(asset==null)continue;String name=asset.optString("name"),url=asset.optString("browser_download_url");if(!allowed(url)||!new URL(url).getHost().equals("github.com")||!new URL(url).getPath().startsWith("/yzhao2864-boop/rain-reminder/releases/download/"+tag+"/"))continue;if(name.equals("RainReminder-"+v+"-SHA256.txt"))checksum=url;if(!name.equals("RainReminder-"+v+"-test.apk"))continue;long size=asset.optLong("size");if(size<=0||size>MAX_APK)continue;found=new Info();found.version=v;found.url=url;found.size=size;found.notes=release.optString("body");String digest=asset.optString("digest");found.sha=digest.matches("sha256:[a-fA-F0-9]{64}")?digest.substring(7).toLowerCase(Locale.ROOT):"";}
 if(found!=null){found.checksum=checksum;if(found.sha.isEmpty()&&checksum.isEmpty())throw new IOException("新版缺少文件校验信息，请稍后重试");if(best==null||compare(found.version,best.version)>0)best=found;}}return best;}
 static Info latest(Context c){try{Info info=Info.from(new JSONObject(prefs(c).getString("latest","{}")));return info.version.matches("[0-9]+(?:\\.[0-9]+)+")&&compare(info.version,version(c))>0?info:null;}catch(Exception e){return null;}}
 static File folder(Context c){return new File(c.getCacheDir(),"updates");}static File readyFile(Context c){return new File(folder(c),"verified.apk");}
 static boolean ready(Context c){try{return readyFile(c).isFile()&&compare(prefs(c).getString("readyVersion","0"),version(c))>0;}catch(Exception e){return false;}}
 static void cleanup(Context c){if(busy)return;try{String v=prefs(c).getString("readyVersion","");if(!v.isEmpty()&&compare(v,version(c))<=0){readyFile(c).delete();prefs(c).edit().remove("readyVersion").remove("readySha").remove("waitingPermission").apply();}}catch(Exception ignored){}}
 static void changed(){main.post(()->{for(Runnable r:listeners)r.run();});}
 static void maybeCheck(Context c){cleanup(c);if(prefs(c).getBoolean("auto",true)&&System.currentTimeMillis()-prefs(c).getLong("attempt",0)>=24*60*60*1000L)check(c);}
 static synchronized void check(Context context){if(busy)return;Context c=context.getApplicationContext();busy=true;phase="checking";message="正在检查更新…";progress=-1;prefs(c).edit().putLong("attempt",System.currentTimeMillis()).apply();changed();new Thread(()->{try{JSONArray releases;try{releases=new JSONObject(readText(FEED,512*1024)).getJSONArray("releases");}catch(Exception unavailable){releases=new JSONArray(readText(API_FEED,2*1024*1024));}Info info=select(releases,version(c));prefs(c).edit().putString("latest",info==null?"":info.json().toString()).putLong("checked",System.currentTimeMillis()).apply();phase=ready(c)?"ready":"idle";message=info==null?"当前已是最新版":"发现新版本 "+info.version;}catch(Exception error){phase="error";message="检查失败，请检查网络后重试。";}finally{busy=false;changed();}},"app-update-check").start();}
 static HttpURLConnection connect(String address)throws Exception{for(int redirects=0;redirects<6;redirects++){if(!allowed(address))throw new IOException("更新地址不受支持");HttpURLConnection connection=(HttpURLConnection)new URL(address).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(20000);connection.setRequestProperty("User-Agent","RainReminder-App-Updater");connection.setRequestProperty("Accept","application/vnd.github+json,application/octet-stream;q=0.9,text/plain;q=0.8");int code=connection.getResponseCode();if(code>=300&&code<400){String location=connection.getHeaderField("Location");String next=location==null?"":new URL(new URL(address),location).toString();connection.disconnect();address=next;continue;}if(code!=200){connection.disconnect();throw new IOException("更新服务暂不可用（"+code+"）");}return connection;}throw new IOException("更新地址跳转过多");}
 static String readText(String url,int limit)throws Exception{HttpURLConnection connection=connect(url);try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>limit)throw new IOException("更新信息过大");out.write(buf,0,n);}return out.toString("UTF-8");}finally{connection.disconnect();}}
 static String hash(File file)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] data=new byte[65536];int n;while((n=in.read(data))!=-1)digest.update(data,0,n);}StringBuilder out=new StringBuilder();for(byte b:digest.digest())out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
 static Set<String> signers(PackageInfo p)throws Exception{if(p==null||p.signingInfo==null)throw new IOException("无法读取更新包签名");Set<String> keys=new HashSet<>();for(android.content.pm.Signature s:p.signingInfo.getApkContentsSigners())keys.add(android.util.Base64.encodeToString(s.toByteArray(),android.util.Base64.NO_WRAP));return keys;}
 static void verifyPackage(Context c,File file,String expected)throws Exception{PackageManager pm=c.getPackageManager();PackageInfo local=pm.getPackageInfo(c.getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES),remote=pm.getPackageArchiveInfo(file.getPath(),PackageManager.GET_SIGNING_CERTIFICATES);if(remote==null||!c.getPackageName().equals(remote.packageName))throw new IOException("不是本应用的更新包");if(remote.getLongVersionCode()<=local.getLongVersionCode()||!expected.equals(remote.versionName))throw new IOException("更新版本不符，请重新检查更新");Set<String> a=signers(local),b=signers(remote);if(a.isEmpty()||!a.equals(b))throw new IOException("更新包签名不符，已停止安装");}
 static synchronized void download(Context context,Info info){if(busy||info==null)return;Context c=context.getApplicationContext();busy=true;cancelled=false;progress=0;phase="downloading";message="正在下载新版…";changed();new Thread(()->{File part=new File(folder(c),"download.part");HttpURLConnection connection=null;try{if(!folder(c).isDirectory()&&!folder(c).mkdirs())throw new IOException("无法创建下载目录");if(folder(c).getUsableSpace()<info.size+4*1024*1024)throw new IOException("手机存储空间不足");String expected=info.sha;if(expected.isEmpty()){String text=readText(info.checksum,4096).trim();java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?i)^([a-f0-9]{64})(?:\\s|$)").matcher(text);if(!m.find())throw new IOException("无法读取文件校验信息");expected=m.group(1).toLowerCase(Locale.ROOT);}connection=connect(info.url);long total=0;try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(part)){byte[] data=new byte[65536];int n,previous=-1;while((n=in.read(data))!=-1){if(cancelled)throw new InterruptedIOException("下载已取消");total+=n;if(total>info.size||total>MAX_APK)throw new IOException("下载文件大小不符");out.write(data,0,n);int value=(int)(total*100/info.size);if(value!=previous){progress=value;previous=value;changed();}}}if(cancelled)throw new InterruptedIOException("下载已取消");if(total!=info.size||!expected.equals(hash(part)))throw new IOException("文件下载不完整，请重试");verifyPackage(c,part,info.version);if(cancelled)throw new InterruptedIOException("下载已取消");File ready=readyFile(c);if(ready.exists()&&!ready.delete())throw new IOException("无法清理旧安装包");if(!part.renameTo(ready))throw new IOException("无法保存安装包");if(!prefs(c).edit().putString("readyVersion",info.version).putString("readySha",expected).commit())throw new IOException("无法保存更新状态");phase="ready";message="下载完成，可以安装新版";progress=100;}catch(Exception error){part.delete();phase=cancelled?"idle":"error";message=cancelled?"下载已取消":error.getMessage()==null?"下载失败，请重试":error.getMessage();}finally{if(connection!=null)connection.disconnect();busy=false;changed();}},"app-update-download").start();}
 static Intent installIntent(Context c){Uri uri=Uri.parse("content://"+c.getPackageName()+".updates/verified.apk");Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("应用更新",uri));return intent;}
 static void install(Activity a){if(!ready(a)){message="请先下载新版";changed();return;}if(!a.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(a).setTitle("允许本应用安装更新").setMessage("首次更新需要在系统页面允许“待课”安装应用，返回后继续。只用于安装本应用的新版。").setPositiveButton("前往设置",(d,n)->{prefs(a).edit().putBoolean("waitingPermission",true).apply();try{a.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+a.getPackageName())));}catch(Exception e){message="请在系统设置中允许本应用安装更新";changed();}}).setNegativeButton("取消",null).show();return;}new Thread(()->{try{File file=readyFile(a);if(!prefs(a).getString("readySha","").equals(hash(file)))throw new IOException("安装包校验失败，请重新下载");verifyPackage(a,file,prefs(a).getString("readyVersion",""));a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed())try{a.startActivity(installIntent(a));}catch(Exception e){message="无法打开系统安装页面，请重试";changed();}});}catch(Exception e){message=e.getMessage();phase="error";changed();}},"app-update-install").start();}
}
